pm.test('Status code es 200', function () {
    pm.response.to.have.status(200);
});

pm.test('Devuelve al menos una cuota vencida', function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.data.length).to.be.above(0);
});

pm.test('Todas las cuotas devueltas están en estado vencida', function () {
    var jsonData = pm.response.json();
    jsonData.data.forEach(function (cuota) {
        pm.expect(cuota.estado).to.eql('vencida');
    });
});

pm.test('Las cuotas vencidas no tienen fecha de pago registrada', function () {
    var jsonData = pm.response.json();
    jsonData.data.forEach(function (cuota) {
        pm.expect(cuota.fecha_pago).to.be.null;
    });
});

pm.test('Tiempo de respuesta menor a 3000ms', function () {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});
